// Writes samples/sample-large.urdf: a made-up robot with 150 links (a body, eight four-joint legs
// and a 100-segment tail), to check that large robots stay responsive. Output is MIT like the repo.
//   node tools/urdf/make-urdf-samples.mjs
import { writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..')
const f = (x) => String(Number(x.toFixed(6)))
const out = [
  '<?xml version="1.0"?>',
  '<!-- Generated by tools/urdf/make-urdf-samples.mjs for File Preview (MIT): a made-up robot with',
  '     150 links (body, eight four-joint legs, a 100-segment tail) for the large-robot check. -->',
  '<robot name="large_test_robot">',
  '  <material name="shell"><color rgba="0.25 0.55 0.65 1"/></material>',
  '  <material name="leg"><color rgba="0.85 0.85 0.88 1"/></material>',
  '  <material name="tail_a"><color rgba="0.9 0.5 0.2 1"/></material>',
  '  <material name="tail_b"><color rgba="0.3 0.3 0.32 1"/></material>',
  '  <link name="body">',
  '    <visual><geometry><box size="0.8 0.5 0.15"/></geometry><material name="shell"/></visual>',
  '    <collision><geometry><box size="0.8 0.5 0.15"/></geometry></collision>',
  '  </link>'
]
let links = 1
for (let leg = 0; leg < 8; leg++) {
  const side = leg < 4 ? 1 : -1
  const x = -0.3 + (leg % 4) * 0.2
  let parent = 'body'
  for (let s = 0; s < 4; s++) {
    const name = `leg${leg}_seg${s}`
    const len = [0.06, 0.18, 0.22, 0.12][s]
    const origin = s === 0 ? `${f(x)} ${f(side * 0.25)} 0` : `0 0 ${f(-[0.06, 0.18, 0.22][s - 1])}`
    const rpy = s === 0 ? `${f(side * -1.2)} 0 0` : s === 2 ? '0 0.9 0' : '0 0 0'
    const axis = s === 0 ? '0 0 1' : '0 1 0'
    out.push(
      `  <joint name="${name}_joint" type="revolute">`,
      `    <parent link="${parent}"/><child link="${name}"/>`,
      `    <origin xyz="${origin}" rpy="${rpy}"/><axis xyz="${axis}"/>`,
      `    <limit lower="-1.2" upper="1.2" effort="10" velocity="2"/>`,
      `  </joint>`,
      `  <link name="${name}">`,
      `    <visual><origin xyz="0 0 ${f(-len / 2)}"/><geometry><cylinder radius="${f(0.025 - s * 0.004)}" length="${f(len)}"/></geometry><material name="leg"/></visual>`,
      `    <collision><origin xyz="0 0 ${f(-len / 2)}"/><geometry><cylinder radius="${f(0.03 - s * 0.004)}" length="${f(len)}"/></geometry></collision>`,
      `  </link>`
    )
    parent = name
    links++
  }
  out.push(
    `  <joint name="leg${leg}_foot_joint" type="fixed"><parent link="${parent}"/><child link="leg${leg}_foot"/><origin xyz="0 0 -0.12"/></joint>`,
    `  <link name="leg${leg}_foot"><visual><geometry><sphere radius="0.025"/></geometry><material name="tail_b"/></visual></link>`
  )
  links++
}
let parent = 'body'
for (let i = 0; i < 100; i++) {
  const name = `tail_${String(i).padStart(3, '0')}`
  const r = 0.05 * Math.pow(0.985, i)
  out.push(
    `  <joint name="${name}_joint" type="${i % 10 === 9 ? 'continuous' : 'revolute'}">`,
    `    <parent link="${parent}"/><child link="${name}"/>`,
    `    <origin xyz="${i === 0 ? '-0.42' : f(-2.1 * 0.05 * Math.pow(0.985, i - 1))} 0 0" rpy="0 ${i === 0 ? '0' : '0.03'} ${f(0.06 * Math.sin(i / 6))}"/>`,
    `    <axis xyz="${i % 2 ? '0 1 0' : '0 0 1'}"/>`,
    i % 10 === 9 ? '' : `    <limit lower="-0.4" upper="0.4" effort="5" velocity="2"/>`,
    `  </joint>`,
    `  <link name="${name}">`,
    `    <visual><origin xyz="${f(-r)} 0 0" rpy="0 1.5707963 0"/><geometry><capsule radius="${f(r * 0.9)}" length="${f(r * 0.4)}"/></geometry><material name="${i % 2 ? 'tail_a' : 'tail_b'}"/></visual>`,
    `  </link>`
  )
  parent = name
  links++
}
out.push('</robot>', '')
writeFileSync(join(ROOT, 'samples', 'sample-large.urdf'), out.filter((l) => l !== '').join('\n'))
console.log(`samples/sample-large.urdf: ${links} links`)
